import pathlib
pathlib.Path(__file__).resolve().parent.joinpath("out").mkdir(exist_ok=True)
INDEX=pathlib.Path(__file__).resolve().parent.parent.joinpath("index.html").as_uri()
import asyncio
from playwright.async_api import async_playwright
SCR=str(pathlib.Path(__file__).resolve().parent/"out")+"/"
from helpers import HELP
async def main():
  async with async_playwright() as p:
    b=await p.chromium.launch();pg=await b.new_page(viewport={"width":1280,"height":720})
    errs=[];pg.on("pageerror",lambda e:print("ERR",str(e),(e.stack or "")[:500]))
    await pg.goto(INDEX);await pg.wait_for_timeout(500)
    await pg.click("#btn-new");await pg.wait_for_timeout(200);await pg.click("#cc-go");await pg.wait_for_timeout(300)
    await pg.evaluate(HELP)
    await pg.evaluate("(()=>{const _d=window.__drain;window.__drain=()=>{let n=0,k=0;do{k=_d();n+=k;const c=document.getElementById('casas');if(c&&!c.hidden){document.getElementById('casas-go').click();k=1;}}while(k>0&&n<400);return n;};})()");await pg.evaluate("__drain()")
    await pg.evaluate("(()=>{const X=ensureX();X.att=Object.assign(X.att||{},{enc:30,gua:30,met:30,mus:30});})()")
    await pg.evaluate("Qs.m0={stage:4,prog:0,done:true};Qs.m1={stage:11,prog:0,done:true};S.house='raiz';S.flags.side='island';S.flags.friends=true;S.spells=['chispa','rafaga'];S.lvl=4;S.xp=400;ensureX();refreshTracker()")
    await pg.evaluate("const _h=haloAt;haloAt=function(x,y,r,rgb,a){if(!isFinite(x)||!isFinite(y)||!isFinite(r)){console.log('BAD',x,y,r,a,S.minutes,camX,camY,S.px,S.py,darkness());return;}_h(x,y,r,rgb,a)}")
    pg.on("console",lambda m:print("CON",m.text[:1500]) if ("BAD" in m.text or "NANPY" in m.text) else None)
    await pg.evaluate("""(()=>{let v=S.py,w=S.px,mm=S.minutes;let n=0;Object.defineProperty(S,'py',{get(){return v},set(x){if(!isFinite(x)&&n++<3)console.log('NANPY py',new Error().stack);v=x},configurable:true});Object.defineProperty(S,'px',{get(){return w},set(x){if(!isFinite(x)&&n++<3)console.log('NANPY px',new Error().stack);w=x},configurable:true});Object.defineProperty(S,'minutes',{get(){return mm},set(x){if(!isFinite(x)&&n++<3)console.log('NANPY min',new Error().stack);mm=x},configurable:true});})()""")
    st=lambda: pg.evaluate("JSON.stringify(['c2','c3','c4'].map(q=>qStage(q)))+' curso '+S.x.curso+' pf '+pauseFlag+' dlg '+document.getElementById('dialog').hidden+' fade '+document.getElementById('fade').className")
    async def talk(id):
      await pg.evaluate(f"(()=>{{const n=NPC['{id}'];S.px=n.px;S.py=n.py+14;S.dir='up';TALK['{id}']();}})()");await pg.wait_for_timeout(100);await pg.evaluate("__drain()");await pg.wait_for_timeout(100)
    async def go(x,y,wait=1200):
      await pg.evaluate(f"__go({x},{y},12)");await pg.wait_for_timeout(wait);await pg.evaluate("__drain()");await pg.wait_for_timeout(200)
