      await pg.wait_for_timeout(400);await pg.evaluate(f"for(const f of foes)if(f.type==='{t}')hitFoe(f,999,0,0)");await pg.wait_for_timeout(300);await pg.evaluate("__drain()");await pg.wait_for_timeout(200)
